        private void DrawSparklineOnCanvas(System.Windows.Controls.Canvas? canvas,
            float[] data, int dataIdx, WpfColor color)
        {
            if (canvas == null) return;
            double w = canvas.ActualWidth, h = canvas.ActualHeight;
            // If canvas has no size yet (hidden by skeleton overlay), schedule retry after layout
            if (!double.IsFinite(w) || !double.IsFinite(h) || w < 2 || h < 2)
            {
                Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Loaded, new Action(() =>
                {
                    double w2 = canvas.ActualWidth, h2 = canvas.ActualHeight;
                    if (w2 >= 10 && h2 >= 5) DrawSparklineOnCanvas(canvas, data, dataIdx, color);
                }));
                return;
            }
            int count = Math.Min(dataIdx, ChartPoints);
            if (count < 2) return;
            int startIdx = dataIdx >= ChartMaxPoints ? dataIdx % ChartMaxPoints : (dataIdx > ChartPoints ? dataIdx - ChartPoints : 0);

            // Padding so dot at 100% / right edge is never clipped by RenderTargetBitmap
            const double pL = 4, pR = 6, pT = 10, pB = 4;
            double cW = w - pL - pR;
            double cH = h - pT - pB;

            var pts = new List<System.Windows.Point>();
            for (int i = 0; i < count; i++)
            {
                float v = data[(startIdx + i) % ChartMaxPoints];
                if (float.IsNaN(v)) { pts.Clear(); continue; }
                // Anchor to right edge: older data appears left, newest at right
                double xFrac = (double)(ChartPoints - count + i) / (ChartPoints - 1);
                double x = pL + xFrac * cW;
                double y = pT + cH - Math.Max(0, Math.Min(1, v / 100.0)) * cH;
                pts.Add(new System.Windows.Point(x, y));
            }
            if (pts.Count < 2) return;

            if (!_dvCache.TryGetValue(canvas, out var dv))
            {
                dv = new DrawingVisual();
                _dvCache[canvas] = dv;
            }
            using (var dc = dv.RenderOpen())
            {
                if (SettingsService.Current.ShowChartGridlines)
                {
                    for (int gi = 1; gi < 4; gi++)
                    {
                        double gx = pL + cW * gi / 4.0;
                        DrawGridLine(dc, new System.Windows.Point(gx, pT), new System.Windows.Point(gx, pT + cH));
                    }
                }

                // Filled gradient area
                var fillPg = new System.Windows.Media.PathGeometry();
                var fillPf = new System.Windows.Media.PathFigure
                    { StartPoint = new System.Windows.Point(pts[0].X, pT + cH), IsClosed = true };
                fillPf.Segments.Add(new System.Windows.Media.LineSegment(pts[0], true));
                for (int pi = 1; pi < pts.Count; pi++)
                    fillPf.Segments.Add(new System.Windows.Media.LineSegment(pts[pi], true));
                fillPf.Segments.Add(new System.Windows.Media.LineSegment(
                    new System.Windows.Point(pts[pts.Count - 1].X, pT + cH), true));
                fillPg.Figures.Add(fillPf);
                fillPg.Freeze();
                uint _sparkFillKey = ((uint)color.R << 16) | ((uint)color.G << 8) | color.B;
                if (!_fillBrushCache.TryGetValue(_sparkFillKey, out var fillBr))
                {
                    fillBr = new System.Windows.Media.LinearGradientBrush(
                        WpfColor.FromArgb(50, color.R, color.G, color.B),
                        WpfColor.FromArgb(5,  color.R, color.G, color.B),
                        new System.Windows.Point(0, 0), new System.Windows.Point(0, 1));
                    fillBr.Freeze();
                    _fillBrushCache[_sparkFillKey] = fillBr;
                }
                dc.DrawGeometry(fillBr, null, fillPg);

                var linePg = BuildSmoothPath(pts);
                var linePen = GetCachedLinePen(color, 1.5);
                dc.DrawGeometry(null, linePen, linePg);

                if (pts.Count > 0)
                {
                    var last = pts[^1];
                    uint dotKey = ((uint)color.R << 16) | ((uint)color.G << 8) | color.B;
                    if (!_dotBrushCache.TryGetValue(dotKey, out var dotBr))
                    {
                        dotBr = new SolidColorBrush(color);
                        dotBr.Freeze();
                        _dotBrushCache[dotKey] = dotBr;
                    }
                    dc.DrawEllipse(dotBr, null, last, 3.5, 3.5);
                }
            }
            RenderToCanvas(canvas, dv, w, h);
        }

        /// <summary>Builds a smooth bezier PathGeometry through the given points (Catmull-Rom tension 0.35).</summary>
        private static System.Windows.Media.PathGeometry BuildSmoothPath(List<System.Windows.Point> pts, bool closed = false)
        {
            var pg = new System.Windows.Media.PathGeometry();
            var pf = new System.Windows.Media.PathFigure { StartPoint = pts[0], IsClosed = closed };
            const double tension = 0.35;
            if (pts.Count == 2)
            {
                pf.Segments.Add(new System.Windows.Media.LineSegment(pts[1], true));
            }
            else
            {
                for (int i = 0; i < pts.Count - 1; i++)
                {
                    var p0 = pts[Math.Max(0, i - 1)];
                    var p1 = pts[i];
                    var p2 = pts[i + 1];
                    var p3 = pts[Math.Min(pts.Count - 1, i + 2)];
                    var cp1 = new System.Windows.Point(
                        p1.X + (p2.X - p0.X) * tension / 3.0,
                        p1.Y + (p2.Y - p0.Y) * tension / 3.0);
                    var cp2 = new System.Windows.Point(
                        p2.X - (p3.X - p1.X) * tension / 3.0,
                        p2.Y - (p3.Y - p1.Y) * tension / 3.0);
                    pf.Segments.Add(new System.Windows.Media.BezierSegment(cp1, cp2, p2, true));
                }
            }
            pg.Figures.Add(pf);
            return pg;
        }

        /// <summary>
        /// Updates the live Dashboard cards that do not depend on TempReader/LHM: CPU%, RAM%, Disk R/W, Network.
        /// Works without Admin too. Called both from OnTempTick (when a snapshot is available) and directly (when _tempReader is null).
        /// </summary>
        private void UpdateDashboardLiveCards()
        {
            // At start-up _currentPanel = "" — the Dashboard is the default panel.
            // Another page or a hidden window: only the data is recorded, nothing is drawn.
            if ((_currentPanel != "Dashboard" && _currentPanel != "") || IsUiHidden)
            {
                PushDashboardChartDataAlways();
                return;
            }

            if (TxtDashLastUpdate != null)
                TxtDashLastUpdate.Text = $"↻  {DateTime.Now:HH:mm:ss}";

            // If the canvases have no size yet, force layout and retry
            bool canvasesReady = (SparkDiskActivity?.ActualWidth ?? 0) > 10 &&
                                 (SparkNetActivity?.ActualWidth  ?? 0) > 10;
            if (!canvasesReady)
            {
                PanelDashboard?.UpdateLayout();
                Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Render, new Action(() =>
                {
                    try { UpdateDashboardLiveCardsInternal(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                }));
                return;
            }

            UpdateDashboardLiveCardsInternal();
        }

        private void PushDashboardChartDataAlways()
        {
            try
            {
                float cpuPct = Math.Max(0f, _cachedCpuPct >= 0 ? _cachedCpuPct : 0f);
                float gpuPct = 0f;
                if (_lastTempSnap?.GpuLoadPct.HasValue == true && _lastTempSnap.GpuLoadPct.Value >= 0)
                {
                    gpuPct = _lastTempSnap.GpuLoadPct.Value;
                    _cachedGpuPct = gpuPct;
                }
                else if (_cachedGpuPct > 0) gpuPct = _cachedGpuPct;

                float ramPct = 0f;
                try
                {
                    var (usedMB, totalMB) = SMDWin.Services.WmiCache.Instance.GetRamUsage();
                    if (totalMB > 0) ramPct = (float)(usedMB / (double)totalMB * 100.0);
                }
                catch (Exception ex) { AppLogger.Debug(ex.Message); }

                float diskRead = _emaDiskRead, diskWrite = _emaDiskWrite;
                float netDown = Math.Max(0f, _emaNetDown);
                float netUp   = Math.Max(0f, _emaNetUp);

                float pingMs = float.NaN;
                for (int i = _pingHistory.Length - 1; i >= 0; i--)
                    if (!float.IsNaN(_pingHistory[i])) { pingMs = _pingHistory[i]; break; }

                float cpuTempRaw = _lastTempSnap?.CpuTemp ?? float.NaN;
                float gpuTempRaw = _lastTempSnap?.GpuTemp ?? float.NaN;
                if (float.IsNaN(cpuTempRaw) && !float.IsNaN(_emaCpuTemp) && _emaCpuTemp > 0 && CpuTempCacheStillFresh) cpuTempRaw = _emaCpuTemp;
                if (float.IsNaN(gpuTempRaw) && !float.IsNaN(_emaGpuTemp) && _emaGpuTemp > 0 && GpuTempCacheStillFresh) gpuTempRaw = _emaGpuTemp;
                if (float.IsNaN(gpuTempRaw) && GpuTempCacheStillFresh) gpuTempRaw = _lastKnownGpuTemp;

                float cpuTemp = !float.IsNaN(_emaCpuTemp) && _emaCpuTemp > 0 && CpuTempCacheStillFresh
                    ? _emaCpuTemp
                    : (!float.IsNaN(cpuTempRaw) && cpuTempRaw > 0 ? cpuTempRaw : float.NaN);
                float gpuTemp = !float.IsNaN(_emaGpuTemp) && _emaGpuTemp > 0 && GpuTempCacheStillFresh
                    ? _emaGpuTemp
                    : (!float.IsNaN(gpuTempRaw) && gpuTempRaw > 0 ? gpuTempRaw
                        : (GpuTempCacheStillFresh ? _lastKnownGpuTemp : float.NaN));
                // _lastKnownGpuTempUtc is updated ONLY from real reads (above), not from the cached value — otherwise a GPU temperature
                // that disappeared would stay shown forever.

                // charts paused (Off, window hidden): nothing to write; throttling detection carries on
                int dbStepsA = IsUiHidden && BgRec == BgRecMode.Off ? 0 : ComputeDbCatchUpSteps();
                for (int s = 0; s < dbStepsA; s++)
                {
                    int idx = _dbHead % DashBufSize;
                    _dbCpu[idx] = cpuPct; _dbGpu[idx] = gpuPct; _dbRam[idx] = ramPct;
                    _dbDiskR[idx] = diskRead; _dbDiskW[idx] = diskWrite;
                    _dbNetDown[idx] = netDown; _dbNetUp[idx] = netUp; _dbPing[idx] = pingMs;
                    _dbCpuTemp[idx] = cpuTemp; _dbGpuTemp[idx] = gpuTemp;
                    _dbHead++;
                    _dbCount = Math.Min(_dbCount + 1, DashBufSize);
                }
                if (dbStepsA > 0) _dbLastDataTime = DateTime.UtcNow;

                for (int s = 0; s < dbStepsA; s++)
                    PushToQueues(cpuPct, gpuPct, ramPct, diskRead, diskWrite,
                                 netDown, netUp, pingMs, cpuTemp, gpuTemp);

                LogSensorSample(cpuPct, ramPct, pingMs);
                SampleThrottleAndStressRuns(cpuTempRaw, gpuTemp);
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }
        }

        /// <summary>One sample for throttling detection and for the stress test result (Health).
        /// Called on every tick, whatever page is shown: the detector works with time windows and needs continuous readings.</summary>
        private void SampleThrottleAndStressRuns(float cpuTempRaw, float gpuTemp)
        {
            SampleStressRuns(cpuTempRaw, gpuTemp, _lastThrottle);
            CheckStressThermalStop(cpuTempRaw, gpuTemp);
            if (_tempReader != null) _throttleDetector.TjMaxC = _tempReader.EstimatedTjMaxC;
            float load = _cachedCpuPct;
            float temp = cpuTempRaw;   // the raw value, not the average: the detector wants the current temperature
            // the real core frequency (sensors): on many processors the Windows counter shows only the base frequency
            float clock = _lastTempSnap?.CpuFreqMHz is float f && f > 0 ? f : float.NaN;
            // fire-and-forget: performance counters may take a while, they are not read on the UI thread
            _ = Task.Run(() =>
            {
                try
                {
                    var tsnap = _throttleDetector.Read(temp, load, clock);
                    if (tsnap != null) _lastThrottle = tsnap;
                }
                catch (Exception ex) { AppLogger.Debug(ex.Message); }
            });
        }

        /// <summary>The sensor log (CSV) and the registry export, on every tick, whatever page is shown and even with the window hidden.</summary>
        private void LogSensorSample(float cpuPct, float ramPct, float pingMs)
        {
            if (DateTime.UtcNow.Second % 5 == 0)
            {
                var s = _lastTempSnap; var c = cpuPct; var r = ramPct;
                if (SettingsService.Current.ExportSensorsToRegistry) _ = Task.Run(() => ExportToRegistry(s, c, r));   // registry writes are not done on the UI thread
            }

            if (!_sensorLogger.Enabled) return;
            var snap = _lastTempSnap;
            _sensorLogger.Log(
                cpuTempC:   snap?.CpuTemp,
                gpuTempC:   snap?.GpuTemp,
                cpuLoadPct: cpuPct >= 0 ? cpuPct : (float?)null,
                gpuLoadPct: snap?.GpuLoadPct,
                ramPct:     ramPct >= 0 ? ramPct : (float?)null,
                netDownKBs: _emaNetDown,
                netUpKBs:   _emaNetUp,
                pingMs:     pingMs >= 0 ? pingMs : 0f,
                cpuPowerW:  snap?.CpuPowerW,
                gpuPowerW:  snap?.GpuPowerW,
                vcoreV:     snap?.CpuVCoreV,
                fanRpm1:    snap?.FanSpeeds.Count > 0 ? snap.FanSpeeds[0].Rpm : (float?)null
            );
        }

        private void UpdateDashboardLiveCardsInternal()
        {
            EnsureUiCache();

            // ── 1. Read all the values ──────────────────────────────────────────
            float cpuPct    = Math.Max(0f, _cachedCpuPct >= 0 ? _cachedCpuPct : 0f);
            float gpuPct = 0f;
            if (_lastTempSnap?.GpuLoadPct.HasValue == true && _lastTempSnap.GpuLoadPct.Value >= 0)
            {
                gpuPct = _lastTempSnap.GpuLoadPct.Value;
                _cachedGpuPct = gpuPct;
            }
            else if (_cachedGpuPct > 0)
                gpuPct = _cachedGpuPct;
            else
            {
                // Fallback: read the GPU usage from WMI/DirectX
                try { float g = GetGpuUsagePct(); if (g >= 0) { gpuPct = g; _cachedGpuPct = g; } }
                catch (Exception ex) { AppLogger.Debug(ex.Message); }
            }

            // RAM
            float ramPct = 0f;
            double ramUsedMBSync = 0, ramTotalMBSync = 0;
            try
            {
                var (usedMB, totalMB) = SMDWin.Services.WmiCache.Instance.GetRamUsage();
                if (totalMB > 0) ramPct = (float)(usedMB / (double)totalMB * 100.0);
                ramUsedMBSync = usedMB; ramTotalMBSync = totalMB;
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }

            float diskRead = _emaDiskRead, diskWrite = _emaDiskWrite;

            // Network: the values come from OnTempTick; _emaNetDown and _emaNetUp are already computed there
            float netDown = Math.Max(0f, _emaNetDown);
            float netUp   = Math.Max(0f, _emaNetUp);
            string netAdapterName = "";

            // Ping (the last one in the history)
            float pingMs = float.NaN;
            try
            {
                for (int i = _pingHistory.Length - 1; i >= 0; i--)
                    if (!float.IsNaN(_pingHistory[i])) { pingMs = _pingHistory[i]; break; }
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }

            // Temperature (from the cached snapshot)
            float cpuTempRaw = _lastTempSnap?.CpuTemp ?? float.NaN;
            float gpuTempRaw = _lastTempSnap?.GpuTemp ?? float.NaN;

            var _throttleSnap = _lastThrottle; // use the last value, written by PushDashboardChartDataAlways()

            if (float.IsNaN(cpuTempRaw) && _lastTempSnap != null)
            {
                try
                {
                    var directSnap = _lastTempSnap;
                    if (directSnap?.CpuTemp.HasValue == true && directSnap.CpuTemp.Value > 0)
                        cpuTempRaw = directSnap.CpuTemp.Value;
                    if (directSnap?.GpuTemp.HasValue == true && directSnap.GpuTemp.Value > 0)
                        gpuTempRaw = directSnap.GpuTemp.Value;
                }
                catch (Exception ex) { AppLogger.Debug(ex.Message); }
            }

            if (float.IsNaN(cpuTempRaw) && !float.IsNaN(_emaCpuTemp) && _emaCpuTemp > 0 && CpuTempCacheStillFresh)
                cpuTempRaw = _emaCpuTemp;
            if (float.IsNaN(gpuTempRaw) && !float.IsNaN(_emaGpuTemp) && _emaGpuTemp > 0 && GpuTempCacheStillFresh)
                gpuTempRaw = _emaGpuTemp;
            if (float.IsNaN(gpuTempRaw) && GpuTempCacheStillFresh)
                gpuTempRaw = _lastKnownGpuTemp;

            float cpuTemp = !float.IsNaN(_emaCpuTemp) && _emaCpuTemp > 0 && CpuTempCacheStillFresh
                ? _emaCpuTemp
                : (!float.IsNaN(cpuTempRaw) && cpuTempRaw > 0 ? cpuTempRaw : float.NaN);

            float gpuTemp = !float.IsNaN(_emaGpuTemp) && _emaGpuTemp > 0 && GpuTempCacheStillFresh
                ? _emaGpuTemp
                : (!float.IsNaN(gpuTempRaw) && gpuTempRaw > 0 ? gpuTempRaw
                    : (GpuTempCacheStillFresh ? _lastKnownGpuTemp : float.NaN));
            // _lastKnownGpuTempUtc is updated ONLY from real reads (above), not from the cached value — otherwise a GPU temperature
            // that disappeared would stay shown forever.

            // ── 2. Push into the chart buffers ──────────────────────────────────
            // The circular system (for compatibility with other pages)
            int dbStepsB = ComputeDbCatchUpSteps();
            for (int s = 0; s < dbStepsB; s++)
            {
                int idx = _dbHead % DashBufSize;
                _dbCpu[idx]     = cpuPct;
                _dbGpu[idx]     = gpuPct;
                _dbRam[idx]     = ramPct;
                _dbDiskR[idx]   = diskRead;
                _dbDiskW[idx]   = diskWrite;
                _dbNetDown[idx] = netDown;
                _dbNetUp[idx]   = netUp;
                _dbPing[idx]    = pingMs;
                _dbCpuTemp[idx] = cpuTemp;
                _dbGpuTemp[idx] = gpuTemp;
                _dbHead++;
                _dbCount = Math.Min(_dbCount + 1, DashBufSize);
            }
            _dbLastDataTime = DateTime.UtcNow;

            for (int s = 0; s < dbStepsB; s++)
                PushToQueues(cpuPct, gpuPct, ramPct, diskRead, diskWrite,
                             netDown, netUp, pingMs, cpuTemp, gpuTemp);

            // the dials and the large values get exactly the values just sent to the charts
            SyncDashDials(cpuPct, gpuPct, _lastTempSnap?.GpuLoadPct.HasValue == true || _cachedGpuPct > 0,
                          ramPct, ramUsedMBSync, ramTotalMBSync, cpuTemp, gpuTemp, pingMs, netDown, netUp);

            LogSensorSample(cpuPct, ramPct, pingMs);
            SampleThrottleAndStressRuns(cpuTempRaw, gpuTemp);

            if (FindName("TxtDashCpuTooltip") is System.Windows.Controls.TextBlock cpuTip)
            {
                var snapTip = _lastTempSnap;
                var sb2 = new System.Text.StringBuilder();
                sb2.AppendLine($"Load: {cpuPct:F0}%");
                if (snapTip?.CpuFreqMHz.HasValue == true)
                    sb2.AppendLine($"Freq: {snapTip.CpuFreqMHz.Value/1000f:F2} GHz");
                if (!float.IsNaN(cpuTemp) && cpuTemp > 0)
                    sb2.AppendLine($"Temp: {TempUnit.Fmt(cpuTemp)}");
                if (snapTip?.CpuVCoreV.HasValue == true)
                    sb2.AppendLine($"VCore: {snapTip.CpuVCoreV.Value:F3} V");
                if (snapTip?.CpuPowerW.HasValue == true)
                    sb2.AppendLine($"Power: {snapTip.CpuPowerW.Value:F1} W");
                if (snapTip?.CoreFreqs?.Count > 0)
                {
                    sb2.AppendLine("─────────────");
                    for (int ci = 0; ci < Math.Min(snapTip.CoreFreqs.Count, 8); ci++)
                        sb2.AppendLine($"Core #{ci}: {snapTip.CoreFreqs[ci]/1000f:F2} GHz");
                }
                cpuTip.Text = sb2.ToString().TrimEnd();
            }

            UpdateDashboardRam();

            if (TxtDashDiskActivity != null)
            {
                TxtDashDiskActivity.Text = FormatDiskRW(_emaDiskRead, _emaDiskWrite);
                var (rTxt2, wTxt2) = FormatDiskRWParts(_emaDiskRead, _emaDiskWrite);
                if (TxtDashDiskR != null) TxtDashDiskR.Text = rTxt2;
                if (TxtDashDiskW != null) TxtDashDiskW.Text = wTxt2;
                SyncDiskRWTextColors();
            }
            if (TxtDashNetDown != null) TxtDashNetDown.Text = $"↓ {FormatKBps(_emaNetDown)}";
            if (TxtDashNetUp   != null) TxtDashNetUp.Text   = $"↑ {FormatKBps(_emaNetUp)}";
            SyncNetDownUpTextColors();
            UpdateDashCardsLive(_emaDiskRead, _emaDiskWrite, _emaNetDown, _emaNetUp);
            if (TxtDashNetAdapter != null && !string.IsNullOrEmpty(netAdapterName))
                TxtDashNetAdapter.Text = netAdapterName.Length > 20 ? netAdapterName[..20] + "…" : netAdapterName;
            if (TxtDashLastUpdate != null)
                TxtDashLastUpdate.Text = $"{DateTime.Now:HH:mm:ss}";

            // ── Hero verdict bar + status pills ──────────────────────────────────
            UpdateHeroBar(cpuPct, ramPct, cpuTemp, gpuTemp);
            UpdateComputeStatus(CpuStatusPill, CpuStatusText, cpuPct, cpuTemp, SettingsService.Current.TempWarnCpu, busyAt: 70, idleBelow: 0);
            UpdateComputeStatus(GpuStatusPill, GpuStatusText, gpuPct, gpuTemp, SettingsService.Current.TempWarnGpu, busyAt: 50, idleBelow: 50);
            UpdateStatusPill(RamStatusPill, RamStatusText, ramPct, 90, 75, "critical", "high", "ok");   // the same words as the RAM page

            if (TxtDashRamUsed != null)
            {
                var ramBr = ramPct > 90 ? _brRed : ramPct > 80 ? _brOrange : _brGreen;
                TxtDashRamUsed.Foreground = ramBr;
                if (TxtRamDashSub != null) TxtRamDashSub.Foreground = ramBr;
            }

            float diskMax = Math.Max(diskRead, diskWrite);
            if (FindName("DiskStatusPill") is Border dsp && FindName("DiskStatusText") is TextBlock dst)
            {
                SetStateLabel(dst, CapStatus(diskMax < 1 ? "idle" : diskMax > 500 ? "high" : "active"),
                    diskMax > 500 ? _brOrange
                    : diskMax < 1 ? (System.Windows.Media.Brush)FindResource("TextSecondaryBrush")
                    : _brGreen);
            }

            if (!float.IsNaN(cpuTemp) && FindName("CpuTempPill") is Border ctp && FindName("CpuTempPillText") is TextBlock ctpt)
            {
                var (lbl, br, rgb) = cpuTemp > 90 ? ("critical", _brRed, (239, 68, 68)) : cpuTemp > 75 ? ("hot", _brRed, (239, 68, 68)) : cpuTemp > 60 ? ("warm", _brOrange, (245, 158, 11)) : ("cool", (System.Windows.Media.Brush)_brCoolBlue, (56, 138, 221));
                SetStateLabel(ctpt, CapStatus(lbl), br);
                // a cool processor keeps its component colour; warm / hot switch to the status colours
                if (lbl == "cool" && TryFindResource("CompCpuColor") is WpfColor cpuCol) rgb = (cpuCol.R, cpuCol.G, cpuCol.B);
                _penDashCpuTemp = IsMonoChartMode
                    ? GetSparkPen(MakeChartPen(56, 138, 221, 1.5), cpuTemp, ChartValKind.Temp)
                    : MakeChartPen((byte)rgb.Item1, (byte)rgb.Item2, (byte)rgb.Item3, 2.0);
            }
            if (!float.IsNaN(gpuTemp) && FindName("GpuTempPill") is Border gtp && FindName("GpuTempPillText") is TextBlock gtpt)
            {
                var (lbl, br, rgb) = gpuTemp > 85 ? ("hot", _brRed, (239, 68, 68)) : gpuTemp > 50 ? ("warm", _brOrange, (245, 158, 11)) : ("cool", (System.Windows.Media.Brush)_brCoolBlue, (56, 138, 221));
                SetStateLabel(gtpt, CapStatus(lbl), br);
                if (lbl == "cool" && TryFindResource("CompGpuColor") is WpfColor gpuCol) rgb = (gpuCol.R, gpuCol.G, gpuCol.B);
                _penDashGpuTemp = IsMonoChartMode
                    ? GetSparkPen(MakeChartPen(56, 138, 221, 1.5), gpuTemp, ChartValKind.Temp)
                    : MakeChartPen((byte)rgb.Item1, (byte)rgb.Item2, (byte)rgb.Item3, 2.0);
            }

            if (!float.IsNaN(cpuTemp) && cpuTemp > 0)
            {
                if (FindName("TxtDashHwCpuTemp") is System.Windows.Controls.TextBlock hwct)
                {
                    hwct.Text = $"{TempUnit.Fmt(cpuTemp)}";
                    hwct.Foreground = cpuTemp > 85 ? _brRed : cpuTemp > 70 ? _brOrange : _brGreen;
                }
                if (FindName("TxtDashHwGpuTemp") is System.Windows.Controls.TextBlock hwgt)
                {
                    hwgt.Text = $"{TempUnit.Fmt(gpuTemp)}";
                    hwgt.Foreground = gpuTemp > 85 ? _brRed : gpuTemp > 70 ? _brOrange
                        : new System.Windows.Media.SolidColorBrush(WpfColor.FromRgb(251,146,60));
                }
                _dashCpuTempMin = _dashCpuTempMin == 0 ? cpuTemp : Math.Min(_dashCpuTempMin, cpuTemp);
                _dashCpuTempMax = Math.Max(_dashCpuTempMax, cpuTemp);
                if (FindName("TxtDashCpuMinMax") is System.Windows.Controls.TextBlock cpuMM)
                    cpuMM.Text = $"min {TempUnit.Deg(_dashCpuTempMin)} · max {TempUnit.Deg(_dashCpuTempMax)}";
            }
            if (!float.IsNaN(gpuTemp) && gpuTemp > 0)
            {
                _dashGpuTempMin = _dashGpuTempMin == 0 ? gpuTemp : Math.Min(_dashGpuTempMin, gpuTemp);
                _dashGpuTempMax = Math.Max(_dashGpuTempMax, gpuTemp);
                if (FindName("TxtDashGpuMinMax") is System.Windows.Controls.TextBlock gpuMM)
                    gpuMM.Text = $"min {TempUnit.Deg(_dashGpuTempMin)} · max {TempUnit.Deg(_dashGpuTempMax)}";
                // VRAM inline
                if (FindName("TxtDashGpuVramInline") is System.Windows.Controls.TextBlock vramTb)
                {
                    var vramMB = _lastTempSnap?.GpuMemUsedMB;
                    vramTb.Text = vramMB.HasValue && vramMB.Value > 0 ? $"{vramMB.Value:F0} MB VRAM" : "";
                }
            }

            // ── Ping labels + alert (independent of drawing) ──
            {
                float lastPing = pingMs; // already computed above in the function
                if (!float.IsNaN(lastPing) && lastPing > 0)
                {
                    _dashPingMin = _dashPingMin == 0 ? lastPing : Math.Min(_dashPingMin, lastPing);
                    _dashPingMax = Math.Max(_dashPingMax, lastPing);
                    _dashPingSum += lastPing; _dashPingCount++;
                    float pingAvg = _dashPingSum / _dashPingCount;
                    if (FindName("TxtDashPingAvgMax") is System.Windows.Controls.TextBlock pam)
                        pam.Text = $"max {_dashPingMax:F0} ms"; // the short label "ping 55 · max 90 ms"
                }
                if (TxtDashPingMs != null)
                    TxtDashPingMs.Text = float.IsNaN(lastPing) || lastPing <= 0 ? "—" : $"{lastPing:F0}";
                if (TxtDashPingStatus != null)
                {
                    if (float.IsNaN(lastPing) || lastPing <= 0)
                    {
                        if (_dashPingHasRunOnce && _dashLastPingFailed)
                        {
                            TxtDashPingStatus.Text = _LS("Network", "PingFailed");
                            TxtDashPingStatus.Foreground = _brRed;
                        }
                        else
                        {
                            TxtDashPingStatus.Text = _LS("Network", "PingNoData");
                            TxtDashPingStatus.Foreground = (System.Windows.Media.Brush)(TryFindResource("TextSecondaryBrush") ?? System.Windows.Media.Brushes.Gray);
                        }
                    }
                    else if (lastPing < 50)
                    { TxtDashPingStatus.Text = LanguageService.S("Common", "Excellent"); TxtDashPingStatus.Foreground = _brGreen; }
                    else if (lastPing < 120)
                    { TxtDashPingStatus.Text = LanguageService.S("Common", "Good"); TxtDashPingStatus.Foreground = _brOrange; }
                    else
                    { TxtDashPingStatus.Text = LanguageService.S("Dashboard", "PingHigh"); TxtDashPingStatus.Foreground = _brRed; }
                }
                if (!float.IsNaN(lastPing) && lastPing > 0)
                {
                    var pingBrush = lastPing < 50 ? _brGreen : lastPing < 120 ? _brOrange : _brRed;
                    var pingRgb   = lastPing < 50 ? (34, 197, 94) : lastPing < 120 ? (245, 158, 11) : (239, 68, 68);
                    if (TxtDashPingMs != null) TxtDashPingMs.Foreground = pingBrush;
                    if (FindName("TxtDashPingMsSuffix") is TextBlock pingSuffix) pingSuffix.Foreground = pingBrush;
                    _penDashPingDynamic = IsMonoChartMode
                        ? GetSparkPen(MakeChartPen(34, 197, 94, 2.0))
                        : MakeChartPen((byte)pingRgb.Item1, (byte)pingRgb.Item2, (byte)pingRgb.Item3, 2.0);
                }
                if (DashPingCard != null)
                    UpdateCardAlert(DashPingCard, !float.IsNaN(lastPing) && lastPing >= 120f, ref _pingAlertSince);
            }

            if (_currentPanel == "Disk" || _currentPanel == "Dashboard" || _currentPanel == "")
            {
                try
                {
                    float diskReadNow  = _emaDiskRead;
                    float diskWriteNow = _emaDiskWrite;

                    if (FindName("TxtStorageActivePct") is System.Windows.Controls.TextBlock sapX)
                    {
                        // Below 10% one decimal is shown — on an idle SSD the activity is small but real, otherwise it looks "stuck at 0%"
                        sapX.Text = _lastDiskActivePct < 10f ? $"{_lastDiskActivePct:F1}%" : $"{_lastDiskActivePct:F0}%";
                        sapX.Foreground = _lastDiskActivePct > 90 ? _brRed : _lastDiskActivePct > 70 ? _brOrange : _brGreen;
                    }
                    if (FindName("TxtStorageAvgMs")    is System.Windows.Controls.TextBlock samX)
                        samX.Text = _lastDiskAvgMs < 1 ? "<1" : $"{_lastDiskAvgMs:F1}";
                    if (FindName("TxtStorageLiveRead") is System.Windows.Controls.TextBlock slrX)
                        slrX.Text = FormatKBps(_emaDiskRead);
                    if (FindName("TxtStorageLiveWrite")is System.Windows.Controls.TextBlock slwX)
                        slwX.Text = FormatKBps(_emaDiskWrite);
                }
                catch (Exception ex) { AppLogger.Debug(ex.Message); }
            }

            // ── Detailed tooltips on all cards ─────────────────────────
            {
                var snap = _lastTempSnap;

                // CPU tooltip
                if (FindName("TxtDashCpuTooltip") is System.Windows.Controls.TextBlock tt)
                {
                    var sb = new System.Text.StringBuilder();
                    sb.AppendLine($"Load:  {cpuPct:F0}%");
                    if (snap?.CpuFreqMHz.HasValue == true)
                        sb.AppendLine($"Freq:  {snap.CpuFreqMHz.Value/1000f:F2} GHz");
                    if (!float.IsNaN(cpuTemp) && cpuTemp > 0)
                        sb.AppendLine($"Temp:  {TempUnit.Fmt(cpuTemp)}");
                    if (snap?.CpuVCoreV.HasValue == true)
                        sb.AppendLine($"VCore: {snap.CpuVCoreV.Value:F3} V");
                    if (snap?.CpuPowerW.HasValue == true)
                        sb.AppendLine($"Power: {snap.CpuPowerW.Value:F1} W");
                    if (snap?.CoreFreqs?.Count > 0)
                    {
                        sb.AppendLine("─────────────");
                        for (int ci = 0; ci < Math.Min(snap.CoreFreqs.Count, 8); ci++)
                            sb.AppendLine($"Core #{ci}: {snap.CoreFreqs[ci]/1000f:F2} GHz");
                    }
                    tt.Text = sb.ToString().TrimEnd();
                }

                // GPU tooltip
                if (FindName("TxtDashGpuTooltip") is System.Windows.Controls.TextBlock gtt)
                {
                    var sb = new System.Text.StringBuilder();
                    sb.AppendLine($"Load:  {gpuPct:F0}%");
                    if (!float.IsNaN(gpuTemp) && gpuTemp > 0)
                        sb.AppendLine($"Temp:  {TempUnit.Fmt(gpuTemp)}");
                    if (snap?.GpuMemUsedMB.HasValue == true)
                        sb.AppendLine($"VRAM:  {snap.GpuMemUsedMB.Value:F0} MB used");
                    if (snap?.GpuMemFreqMHz.HasValue == true)
                        sb.AppendLine($"Mem:   {snap.GpuMemFreqMHz.Value:F0} MHz");
                    if (snap?.GpuFreqMHz.HasValue == true)
                        sb.AppendLine($"Clock: {snap.GpuFreqMHz.Value:F0} MHz");
                    gtt.Text = sb.ToString().TrimEnd();
                }

                // RAM tooltip
                if (FindName("TxtDashRamTooltip") is System.Windows.Controls.TextBlock rtt)
                {
                    var sb = new System.Text.StringBuilder();
                    if (_cachedTotalRamMB > 0)
                    {
                        float usedMB = _cachedTotalRamMB - _cachedAvailRamMB;
                        sb.AppendLine($"Total:     {_cachedTotalRamMB/1024f:F1} GB");
                        sb.AppendLine($"Utilizat:  {usedMB/1024f:F1} GB");
                        sb.AppendLine($"Liber:     {_cachedAvailRamMB/1024f:F1} GB");
                        float pctUsed = usedMB / _cachedTotalRamMB * 100f;
                        sb.AppendLine($"Utilizare: {pctUsed:F0}%");
                    }
                    if (_summary?.RamType != null)
                        sb.AppendLine($"Tip:       {_summary.RamType}");
                    rtt.Text = sb.ToString().TrimEnd();
                }

                // CPU TEMP tooltip
                if (FindName("TxtDashCpuTempTooltip") is System.Windows.Controls.TextBlock cttt)
                {
                    var sb = new System.Text.StringBuilder();
                    sb.AppendLine($"{_LS("Stress", "CurrentTemp")}: {TempUnit.Fmt(cpuTemp, 1)}");
                    sb.AppendLine($"{_LS("Stress", "SessionMin")}:  {TempUnit.Fmt(_dashCpuTempMin)}");
                    sb.AppendLine($"{_LS("Stress", "SessionMax")}:  {TempUnit.Fmt(_dashCpuTempMax)}");
                    if (snap?.CpuPowerW.HasValue == true)
                        sb.AppendLine($"Power:        {snap.CpuPowerW.Value:F1} W");
                    sb.AppendLine($"{_LS("Stress", "AlertThreshold")}:  {SettingsService.Current.TempWarnCpu}°C");
                    cttt.Text = sb.ToString().TrimEnd();
                }

                // GPU TEMP tooltip
                if (FindName("TxtDashGpuTempTooltip") is System.Windows.Controls.TextBlock gttt)
                {
                    var sb = new System.Text.StringBuilder();
                    sb.AppendLine($"{_LS("Stress", "CurrentTemp")}: {(float.IsNaN(gpuTemp) ? "—" : $"{TempUnit.Fmt(gpuTemp, 1)}")}");
                    sb.AppendLine($"{_LS("Stress", "SessionMin")}:  {TempUnit.Fmt(_dashGpuTempMin)}");
                    sb.AppendLine($"{_LS("Stress", "SessionMax")}:  {TempUnit.Fmt(_dashGpuTempMax)}");
                    if (snap?.GpuMemUsedMB.HasValue == true)
                        sb.AppendLine($"VRAM:         {snap.GpuMemUsedMB.Value:F0} MB");
                    sb.AppendLine($"{_LS("Stress", "AlertThreshold")}:  {SettingsService.Current.TempWarnGpu}°C");
                    gttt.Text = sb.ToString().TrimEnd();
                }

                // Ping tooltip
                if (FindName("TxtDashPingTooltip") is System.Windows.Controls.TextBlock ptt
                    && _dashPingCount > 0)
                {
                    float avg = _dashPingSum / _dashPingCount;
                    var sb = new System.Text.StringBuilder();
                    sb.AppendLine($"Host:    8.8.8.8 (Google DNS)");
                    sb.AppendLine($"Curent:  {pingMs:F0} ms");
                    sb.AppendLine($"Avg:     {avg:F0} ms");
                    sb.AppendLine($"Min:     {_dashPingMin:F0} ms");
                    sb.AppendLine($"Max:     {_dashPingMax:F0} ms");
                    sb.AppendLine($"Mostre:  {_dashPingCount}");
                    ptt.Text = sb.ToString().TrimEnd();
                }
            }

            if (FindName("TxtDashCpuMinMax2") is System.Windows.Controls.TextBlock cpuMM2)
                cpuMM2.Text = (_dashCpuTempMax > 0) ? $"{TempUnit.Deg(_dashCpuTempMin)}–{TempUnit.Deg(_dashCpuTempMax)}" : "";
            // GPU VRAM in the right footer
            if (FindName("TxtDashGpuVram2") is System.Windows.Controls.TextBlock gpuV2)
            {
                var vramMB = _lastTempSnap?.GpuMemUsedMB;
                gpuV2.Text = vramMB.HasValue && vramMB.Value > 0 ? $"{vramMB.Value:F0} MB" : "";
            }
            // RAM frequency in the right footer
            if (FindName("TxtDashRamFreq2") is System.Windows.Controls.TextBlock ramF2)
            {
                // RamType holds the full info (e.g. "DDR3 · 2×4 GB · 1600 MHz") — extract the frequency
                var ramType = _summary?.RamType ?? "";
                ramF2.Text = string.IsNullOrEmpty(ramType) ? "" : ramType.Split('·').LastOrDefault()?.Trim() ?? "";
            }
            // Public IP (from the cache — updated by the Network page)
            if (FindName("TxtDashLocalIp") is System.Windows.Controls.TextBlock localIp)
            {
                // Use the _lastPublicIp cache if it exists, otherwise the active local IP
                string pubIp = "";
                try { pubIp = _lastPublicIp ?? ""; } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                if (string.IsNullOrEmpty(pubIp))
                {
                    try {
                        var ifaces = System.Net.NetworkInformation.NetworkInterface.GetAllNetworkInterfaces();
                        foreach (var ni in ifaces)
                        {
                            if (ni.OperationalStatus != System.Net.NetworkInformation.OperationalStatus.Up) continue;
                            if (ni.NetworkInterfaceType == System.Net.NetworkInformation.NetworkInterfaceType.Loopback) continue;
                            foreach (var addr in ni.GetIPProperties().UnicastAddresses)
                            {
                                if (addr.Address.AddressFamily == System.Net.Sockets.AddressFamily.InterNetwork &&
                                    !System.Net.IPAddress.IsLoopback(addr.Address) &&
                                    !addr.Address.ToString().StartsWith("169."))
                                { pubIp = addr.Address.ToString(); break; }
                            }
                            if (!string.IsNullOrEmpty(pubIp)) break;
                        }
                    } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                }
                localIp.Text = string.IsNullOrEmpty(pubIp) ? "—" : pubIp;
            }

            // Note: the charts are drawn from OnDashRenderTick at 30 fps
        }

        // ══════════════════════════════════════════════════════════════════════
        // CHART RENDERING — Mission Center style
        // Fixed-length circular buffer (windowSec elements, initialized with 0).
        // On every sample: remove(0) + Add(val). The chart always takes the full width.
        // Smooth: cubic bezier between consecutive points.
        // ══════════════════════════════════════════════════════════════════════

        #pragma warning disable CS0414
        private bool _dashSizeChanged = false;
#pragma warning restore CS0414

        private void OnDashRenderTick(object? sender, EventArgs e)
        {
            if (WindowState == System.Windows.WindowState.Minimized) return;
            if (_currentPanel != "Dashboard" && _currentPanel != "") return;

            // Animations: while the glide lasts, redraw every frame; afterwards only on new data
            double phase = 0;
            if (SettingsService.Current.EnableAnimations && _dashGlideStartUtc != DateTime.MinValue)
                phase = Math.Max(0, 1 - (DateTime.UtcNow - _dashGlideStartUtc).TotalMilliseconds / _dashGlideMs);
            bool gliding = phase > 0 || _dashGlideActive;
            _dashGlideActive = phase > 0;
            if (!_renderDirty && !gliding) return;
            _renderDirty = false;
            _dashGlidePhase = phase;
            // the head of the line moves smoothly to the new value in the first part of the interval (slightly eased at the end)
            if (phase > 0)
            {
                double t = Math.Min(1, (DateTime.UtcNow - _dashGlideStartUtc).TotalMilliseconds / Math.Clamp(_dashGlideMs * 0.45, 100, 600));
                _dashHeadT = 1 - (1 - t) * (1 - t);
            }
            try { DrawDashCharts(); }
            finally { _dashGlidePhase = 0; _dashHeadT = 1; }
        }

        private DateTime _dashGlideStartUtc = DateTime.MinValue, _dashLastDataUtc = DateTime.MinValue;
        private double _dashGlideMs = 1000, _dashGlidePhase, _dashHeadT = 1;
        private bool _dashGlideActive;

        private void DrawDashCharts()
        {

            _cCpu     = _arrCpu;     _cGpu     = _arrGpu;
            _cRam     = _arrRam;     _cDiskR   = _arrDiskR;
            _cDiskW   = _arrDiskW;   _cNetDown = _arrNetDown;
            _cNetUp   = _arrNetUp;   _cPing    = _arrPing;
            _cCpuTemp = _arrCpuTemp; _cGpuTemp = _arrGpuTemp;

            _dashSizeChanged = false;

            EnsureQueues(SettingsService.Current.ChartWindowSeconds);
            bool showFill = SettingsService.Current.ChartShowFill;

            try { DrawChart(SparkCpu,          _cCpu ?? Array.Empty<float>(),     GetSparkPen(_penChartBlue, LastSparkVal(_cCpu), ChartValKind.Percent),        showFill, 0f,   100f); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { DrawChart(SparkGpu,          _cGpu ?? Array.Empty<float>(),     GetSparkPen(_penChartPurple, LastSparkVal(_cGpu), ChartValKind.Percent),        showFill, 0f,   100f); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { DrawChart(SparkRam,          _cRam ?? Array.Empty<float>(),     GetSparkPen(_penChartGreen, LastSparkVal(_cRam), ChartValKind.Percent),        showFill, 0f,   100f); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { DrawChart(SparkDiskActivity, _cDiskR ?? Array.Empty<float>(),   GetSparkPen(_penDiskRead),   showFill, 0f,    -1f, _cDiskW ?? Array.Empty<float>(),  GetSparkPen(_penDiskWrite));  } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { DrawChart(SparkNetActivity,  _cNetDown ?? _arrNetDown, GetSparkPen(_penNetDown),    showFill, 0f,    -1f, _cNetUp ?? _arrNetUp,  GetSparkPen(_penNetUp));      } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { DrawDashTempChart(DashCpuTempChart, _cCpuTemp ?? _arrCpuTemp, _penDashCpuTemp, showFill); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { DrawDashTempChart(DashGpuTempChart, _cGpuTemp ?? _arrGpuTemp, _penDashGpuTemp, showFill); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { DrawChart(DashPingChart,     _cPing ?? _arrPing,    _penDashPingDynamic,   showFill, 0f,    -1f); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            UpdateDashCollecting();
        }

        /// <summary>"Collecting data…" over the temperature charts while they have fewer than 15 points (the first seconds).</summary>
        private void UpdateDashCollecting()
        {
            try
            {
                string text = LanguageService.S("Dashboard", "CollectingData", "Collecting data…");
                foreach (var (name, count) in new[] { ("TxtDashCpuCollecting", _qCpuTemp.Count), ("TxtDashGpuCollecting", _qGpuTemp.Count) })
                    if (FindName(name) is TextBlock t)
                    {
                        var vis = count < 15 && _appStartStopwatch.Elapsed.TotalSeconds < 90 ? Visibility.Visible : Visibility.Collapsed;   // no data after 90 s (e.g. no GPU sensor): hidden
                        if (t.Visibility != vis) t.Visibility = vis;
                        if (vis == Visibility.Visible && t.Text != text) t.Text = text;
                    }
            }
            catch (Exception ex) { AppLogger.Debug($"UpdateDashCollecting: {ex.Message}"); }
        }

        private SMDWin.Services.CircularBuffer _qCpu     = new(3600);
        private SMDWin.Services.CircularBuffer _qGpu     = new(3600);
        private SMDWin.Services.CircularBuffer _qRam     = new(3600);
        private SMDWin.Services.CircularBuffer _qDiskR   = new(3600);
        private SMDWin.Services.CircularBuffer _qDiskW   = new(3600);
        private SMDWin.Services.CircularBuffer _qNetDown = new(3600);
        private SMDWin.Services.CircularBuffer _qNetUp   = new(3600);
        private SMDWin.Services.CircularBuffer _qPing    = new(3600);
        private SMDWin.Services.CircularBuffer _qCpuTemp = new(3600);
        private SMDWin.Services.CircularBuffer _qGpuTemp = new(3600);
        private int _qWindowSec = 0;

        private void EnsureQueues(int windowSec)
        {
            if (_qWindowSec == windowSec) return;
            _qWindowSec = windowSec;
        }

        private void PushToQueues(float cpu, float gpu, float ram,
                                   float diskR, float diskW,
                                   float netDown, float netUp,
                                   float ping, float cpuTemp, float gpuTemp)
        {
            int windowSec = SettingsService.Current.ChartWindowSeconds;
            EnsureQueues(windowSec);

            // ── CPU / GPU / RAM ──────────────────────────────────────────
            // missing value = a gap on the chart (DrawChart skips NaN), not a false 0%
            _qCpu.Push(float.IsFinite(cpu) ? cpu : float.NaN);
            _qGpu.Push(float.IsFinite(gpu) ? gpu : float.NaN);
            _qRam.Push(float.IsFinite(ram) ? ram : float.NaN);

            // ── DISK — rolling average of 5 values + skip the first 5 ticks ────
            // PerformanceCounter returns absurd values on the first calls (a Windows bug).
            // The rolling average removes disk burst spikes.
            _diskWarmupTicks++;
            if (_diskWarmupTicks > 3)
            {
                float dr = (!float.IsNaN(diskR) && diskR >= 0) ? Math.Min(diskR, 4_000_000f) : 0f;
                float dw = (!float.IsNaN(diskW) && diskW >= 0) ? Math.Min(diskW, 4_000_000f) : 0f;
                float curAvgR = 0f; for (int i = 0; i < _rolDiskCnt; i++) curAvgR += _rolDiskR[i];
                if (_rolDiskCnt > 0) curAvgR /= _rolDiskCnt;
                float curAvgW = 0f; for (int i = 0; i < _rolDiskCnt; i++) curAvgW += _rolDiskW[i];
                if (_rolDiskCnt > 0) curAvgW /= _rolDiskCnt;
                if (dr > curAvgR * 1.25f && dr - curAvgR > 10_240f)
                    for (int i = 0; i < 5; i++) _rolDiskR[i] = dr;
                if (dw > curAvgW * 1.25f && dw - curAvgW > 10_240f)
                    for (int i = 0; i < 5; i++) _rolDiskW[i] = dw;
                _rolDiskR[_rolDiskIdx % 5] = dr;
                _rolDiskW[_rolDiskIdx % 5] = dw;
                _rolDiskIdx++;
                _rolDiskCnt = Math.Min(_rolDiskCnt + 1, 5);
                float sumR = 0f, sumW = 0f;
                for (int i = 0; i < _rolDiskCnt; i++) { sumR += _rolDiskR[i]; sumW += _rolDiskW[i]; }
                _qDiskR.Push(sumR / _rolDiskCnt);
                _qDiskW.Push(sumW / _rolDiskCnt);
            }

            // ── NETWORK — rolling average of 10 values ─────────────────────────
            // Wi-Fi is bursty by nature → 0,900,0,900 KB/s alternating.
            // A 10 s rolling average = the real traffic average, without oscillation.
            {
                float nd = Math.Max(0f, float.IsNaN(netDown) ? 0f : netDown);
                float nu = Math.Max(0f, float.IsNaN(netUp)   ? 0f : netUp);
                _rolNetDown[_rolNetIdx % 5] = nd;
                _rolNetUp  [_rolNetIdx % 5] = nu;
                _rolNetIdx++;
                _rolNetCnt = Math.Min(_rolNetCnt + 1, 5);

                int _nc5 = Math.Min(_rolNetCnt, 5); float _sTmpD = 0f, _sTmpU = 0f; for (int i = 0; i < _nc5; i++) { _sTmpD += _rolNetDown[i]; _sTmpU += _rolNetUp[i]; }
                _qNetDown.Push(_sTmpD / _rolNetCnt);
                _qNetUp.Push(_sTmpU / _rolNetCnt);
            }

            if (!float.IsNaN(ping) && ping > 0f)
            {
                _emaPingSmooth = _emaPingSmooth < 0.01f
                    ? ping
                    : 0.30f * ping + 0.70f * _emaPingSmooth;
            }
            // NaN only until the first real ping — DrawChart skips it (an empty chart, not a false 0)
            _qPing.Push(_emaPingSmooth > 0.01f ? _emaPingSmooth : float.NaN);

            _qCpuTemp.Push(SMDWin.Services.SensorValidation.IsPlausibleTemp(cpuTemp) ? cpuTemp : float.NaN);
            _qGpuTemp.Push(SMDWin.Services.SensorValidation.IsPlausibleTemp(gpuTemp) ? gpuTemp : float.NaN);

            // ── SMBIOS — read once, on the first tick ─────────────────────
            if (_smbiosInfo == null)
            {
                try
                {
                    _smbiosInfo = SMDWin.Services.SmbiosReader.Read();
                    SMDWin.Services.SmbiosReader.RefreshSystemSerialFromWmiAsync();
                }
                catch { _smbiosInfo = new SMDWin.Services.SmbiosInfo(); }

                bool smbiosBoardOk = !SMDWin.Services.HardwareInfo.IsJunkBoardValue(_smbiosInfo?.BoardManufacturer ?? "")
                                  || !SMDWin.Services.HardwareInfo.IsJunkBoardValue(_smbiosInfo?.BoardProduct ?? "");
                if (smbiosBoardOk)
                {
                    _boardNameResolved = FormatMachineName(_smbiosInfo?.BoardManufacturer, _smbiosInfo?.BoardProduct);
                }
                else if (!_boardNameResolving)
                {
                    _boardNameResolving = true;
                    _ = Task.Run(() =>
                    {
                        try
                        {
                            using var s2 = SMDWin.Services.WmiHelper.Searcher("SELECT Manufacturer,Product FROM Win32_BaseBoard");
                            using (var __wmiTmp3 = s2.Get())
                            {
                                foreach (System.Management.ManagementObject o in __wmiTmp3)
                            {
                                string wMfg  = o["Manufacturer"]?.ToString()?.Trim() ?? "";
                                string wProd = o["Product"]?.ToString()?.Trim() ?? "";
                                if (!SMDWin.Services.HardwareInfo.IsJunkBoardValue(wMfg) || !SMDWin.Services.HardwareInfo.IsJunkBoardValue(wProd))
                                    _boardNameResolved = FormatMachineName(
                                        SMDWin.Services.HardwareInfo.IsJunkBoardValue(wMfg)  ? "" : wMfg,
                                        SMDWin.Services.HardwareInfo.IsJunkBoardValue(wProd) ? "" : wProd);
                                break;
                            }
                            }
                        }
                        catch (Exception ex) { AppLogger.Debug($"Board WMI fallback: {ex.Message}"); }
                        finally { _boardNameResolving = false; }
                    });
                }
            }

            // Snapshot arrays (1x/sec) — DrawChart reads from arr, not from the queue
            _arrCpu     = _qCpu.ToArray();     _arrGpu     = _qGpu.ToArray();
            _arrRam     = _qRam.ToArray();     _arrDiskR   = _qDiskR.ToArray();
            _arrDiskW   = _qDiskW.ToArray();   _arrNetDown = _qNetDown.ToArray();
            _arrNetUp   = _qNetUp.ToArray();   _arrPing    = _qPing.ToArray();
            _arrCpuTemp = _qCpuTemp.ToArray(); _arrGpuTemp = _qGpuTemp.ToArray();
            _renderDirty = true; // tell the renderer there is new data
            // the chart glide lasts until the next read (see OnDashRenderTick / DrawChart)
            var glideNow = DateTime.UtcNow;
            double gapMs = _dashLastDataUtc == DateTime.MinValue ? 1000 : (glideNow - _dashLastDataUtc).TotalMilliseconds;
            // the whole interval (and 3 s on battery): a lower limit would leave the chart stopped until the next read
            _dashGlideMs = Math.Clamp(gapMs, 120, 6000);
            _dashGlideStartUtc = glideNow;
            _dashLastDataUtc = glideNow;
        }
        private readonly Dictionary<System.Windows.Controls.Canvas, float> _dynMaxCache = new();

        private static float[] SliceLastN(float[] arr, int n)
        {
            if (n <= 0 || arr.Length <= n) return arr;
            var result = new float[n];
            Array.Copy(arr, arr.Length - n, result, 0, n);
            return result;
        }

        private void DrawChart(
            System.Windows.Controls.Canvas? canvas,
            float[] q,
            System.Windows.Media.Pen pen,
            bool showFill, float yMin, float yMax,
            float[]? q2 = null,
            System.Windows.Media.Pen? pen2 = null)
        {
            if (canvas == null) return;
            double w = canvas.ActualWidth, h = canvas.ActualHeight;
            if (!double.IsFinite(w) || !double.IsFinite(h) || w < 6 || h < 6) return;

            bool isDiskActivityCanvas = canvas == SparkDiskActivity || canvas == StorageActivityCanvas
                || canvas == BenchDiskActivityCanvas || canvas == SurfaceDiskActivityCanvas
                || canvas == SmartDiskActivityCanvas;

            bool isPreSlicedDiskCanvas = canvas == StorageActivityCanvas
                || canvas == BenchDiskActivityCanvas || canvas == SurfaceDiskActivityCanvas
                || canvas == SmartDiskActivityCanvas;
            int windowSec = SettingsService.Current.ChartWindowSeconds;
            var raw  = isPreSlicedDiskCanvas ? q  : SliceLastN(q, windowSec);
            var raw2 = isPreSlicedDiskCanvas ? q2 : (q2 != null ? SliceLastN(q2, windowSec) : null);
            // during the glide the point that just left the window is drawn too, left of the edge, so the start of the line leaves
            // the chart smoothly instead of jumping by one step
            bool extraLeft = _dashGlidePhase > 0 && !isPreSlicedDiskCanvas && windowSec > 2
                && q.Length > windowSec && (q2 == null || q2.Length > windowSec);
            if (extraLeft)
            {
                raw = SliceLastN(q, windowSec + 1);
                raw2 = q2 != null ? SliceLastN(q2, windowSec + 1) : null;
            }

            // yMax dinamic — scale-up imediat, decay 2% per frame
            float dynMax = yMax;
            if (dynMax < 0)
            {
                float curMax = 1f;
                foreach (var v in raw)  if (!float.IsNaN(v) && v > curMax) curMax = v;
                if (raw2 != null) foreach (var v in raw2) if (!float.IsNaN(v) && v > curMax) curMax = v;
                curMax *= 1.2f; if (curMax < 1f) curMax = 1f;
                if (canvas == SparkNetActivity)
                {
                    float curDown = 0f, curUp = 0f;
                    foreach (var v in raw)  if (!float.IsNaN(v) && v > curDown) curDown = v;
                    if (raw2 != null) foreach (var v in raw2) if (!float.IsNaN(v) && v > curUp) curUp = v;
                    // The same rule as on the Network page: a 1 MB/s minimum threshold, then autoscale by the visible maximum
                    // (both directions on the same axis), a round step.
                    curMax = NiceNetScale(Math.Max(curDown, curUp));
                }
                if (canvas == SparkDiskActivity || canvas == StorageActivityCanvas
                    || canvas == BenchDiskActivityCanvas || canvas == SurfaceDiskActivityCanvas
                    || canvas == SmartDiskActivityCanvas)
                {
                    float curRead = 0f, curWrite = 0f;
                    foreach (var v in raw)  if (!float.IsNaN(v) && v > curRead) curRead = v;
                    if (raw2 != null) foreach (var v in raw2) if (!float.IsNaN(v) && v > curWrite) curWrite = v;
                    string mediaType = _allDisks != null && _allDisks.Count > 0
                        ? _allDisks[0].MediaType : "SSD";
                    float seed = ScaleService.DefaultDiskMax(mediaType);
                    float scaleRead  = ScaleService.Observe(ScaleService.KeyDiskRead("C"),  curRead,  seed);
                    float scaleWrite = ScaleService.Observe(ScaleService.KeyDiskWrite("C"), curWrite, seed);
                    float diskCeil = Math.Max(scaleRead, scaleWrite);
                    if (diskCeil < seed) diskCeil = seed;
                    if (curMax < diskCeil) curMax = diskCeil;
                }
                if (canvas == DashPingChart)
                {
                    const float pingCeil = 100f; // ms
                    if (curMax > pingCeil)
                    {
                        // Autoscale + visual marking of a large lag (tooltip on the card)
                        if (FindName("TxtDashPingAvgMax") is System.Windows.Controls.TextBlock pam2)
                            pam2.ToolTip = $"⚠ High latency detected: {curMax:F0} ms";
                        // Snap to a multiple of 25 to avoid alternating labels
                        curMax = (float)(Math.Ceiling(curMax / 25.0) * 25.0);
                    }
                    else curMax = pingCeil; // fixed scale
                }
                if (_dynMaxCache.TryGetValue(canvas, out float cached))
                {
                    float decayRate = isDiskActivityCanvas ? 0.90f : 0.98f;
                    dynMax = curMax > cached ? curMax : cached * decayRate;
                    if (dynMax < curMax) dynMax = curMax;
                }
                else dynMax = curMax;
                _dynMaxCache[canvas] = dynMax;
            }
            if (dynMax <= yMin) dynMax = yMin + 1f;
            double range = dynMax - yMin;

            const double pL = 2, pR = 6, pT = 4;
            double pB = isDiskActivityCanvas ? 10 : 4;
            double cW = w - pL - pR, cH = h - pT - pB;
            if (cW < 4 || cH < 4) return;

            var dpiInfo = VisualTreeHelper.GetDpi(canvas);
            double dpi = dpiInfo.PixelsPerDip;
            var ft = _chartTypeface;

            if (!_dvCache.TryGetValue(canvas, out var dv))
            {
                dv = new DrawingVisual();
                _dvCache[canvas] = dv;
            }
            using (var dc = dv.RenderOpen())
            {
                dc.PushClip(new RectangleGeometry(new System.Windows.Rect(pL, 0, Math.Max(0, w - pL), h)));
                // ── Grid lines with numeric labels (the same style as Temp & Stress) ────
                // Compute 3-4 representative grid values
                var gridVals = new System.Collections.Generic.List<float>();
                if (canvas == DashPingChart)
                {
                    // Ping: grid EXACTLY at 25/50/75/100 ms (not fractions of the range, which give imprecise floats)
                    float step = dynMax <= 100f ? 25f : (float)(Math.Ceiling(dynMax / 4.0 / 25.0) * 25.0);
                    for (float v = step; v <= dynMax + 0.5f; v += step)
                        gridVals.Add((float)Math.Round(v));
                }
                else if (yMin == 0f && Math.Abs(dynMax - 100f) < 1f)
                {
                    // 0-100%: grid at 25, 50, 75 + 100 at the top
                    gridVals.AddRange(new float[] { 25f, 50f, 75f, 100f });
                }
                else if (yMin >= 20f && dynMax <= 110f)
                {
                    // Temperatures: grid at 40, 60, 80, 100
                    foreach (int t in new[] { 40, 60, 80, 100 })
                        if (t >= yMin && t <= dynMax) gridVals.Add(t);
                }
                else
                {
                    // Dinamic: 25/50/75/100%
                    gridVals.Add(yMin + (float)(range * 0.25));
                    gridVals.Add(yMin + (float)(range * 0.5));
                    gridVals.Add(yMin + (float)(range * 0.75));
                    gridVals.Add(dynMax); // top
                }

                foreach (float gv in gridVals)
                {
                    double gy = pT + cH * (1.0 - (gv - yMin) / range);
                    if (gy < pT - 1 || gy > pT + cH + 1) continue;
                    DrawGridLine(dc,
                        new System.Windows.Point(pL, gy),
                        new System.Windows.Point(pL + cW, gy));
                }


                const int GapBreakThreshold = 3;
                System.Collections.Generic.List<System.Collections.Generic.List<System.Windows.Point>> BuildRuns(float[] data)
                {
                    var runs = new System.Collections.Generic.List<System.Collections.Generic.List<System.Windows.Point>>();
                    int n = data.Length;
                    System.Collections.Generic.List<System.Windows.Point>? cur = null;
                    int nanStreak = 0;
                    for (int i = 0; i < n; i++)
                    {
                        float v = data[i];
                        if (float.IsNaN(v) || float.IsInfinity(v))
                        {
                            nanStreak++;
                            if (nanStreak >= GapBreakThreshold) cur = null; // a real gap — a new run after it
                            continue; // isolated glitch (below the threshold): skip the point, but do NOT break the current segment
                        }
                        nanStreak = 0;
                        int span = extraLeft ? n - 2 : n - 1;              // pasi vizibili (punctul in plus sta la -1)
                        double xFrac = (double)(extraLeft ? i - 1 : i) / span;
                        double px = pL + xFrac * cW;
                        // animated glide: the last point sits at the edge, the rest start further right
                        if (_dashGlidePhase > 0 && i < n - 1) px = Math.Min(pL + cW, px + _dashGlidePhase * cW / span);
                        double py = pT + cH - Math.Clamp((v - yMin) / range, 0.0, 1.0) * cH;
                        // the head of the line (the last point) moves smoothly from the old value to the new one
                        if (i == n - 1 && _dashHeadT < 1 && n >= 2 && float.IsFinite(data[n - 2]))
                        {
                            double pyPrev = pT + cH - Math.Clamp((data[n - 2] - yMin) / range, 0.0, 1.0) * cH;
                            py = pyPrev + (py - pyPrev) * _dashHeadT;
                        }
                        if (cur == null) { cur = new System.Collections.Generic.List<System.Windows.Point>(); runs.Add(cur); }
                        cur.Add(new System.Windows.Point(px, py));
                    }
                    return runs;
                }

                // ── Helper: draws a series (fill + smooth Bezier line + dot) ─────
                void DrawSeries(float[] data, System.Windows.Media.Pen linePen, bool doFill, bool showValueLabel = false)
                {
                    var runs = BuildRuns(data);
                    int totalPts = 0; foreach (var r in runs) totalPts += r.Count;
                    if (totalPts < 2) return;

                    var lineCol = (linePen.Brush as SolidColorBrush)?.Color
                                  ?? WpfColor.FromRgb(79, 138, 240);

                    void DrawRun(System.Collections.Generic.List<System.Windows.Point> pts)
                    {
                    if (pts.Count < 2) return;
                    if (doFill)
                    {
                        var fg = new StreamGeometry();
                        using (var ctx = fg.Open())
                        {
                            ctx.BeginFigure(new System.Windows.Point(pts[0].X, pT + cH), true, true);
                            ctx.LineTo(pts[0], true, false);
                            const double tension = 0.35;
                            for (int i = 1; i < pts.Count; i++)
                            {
                                var p0 = pts[Math.Max(0, i - 2)];
                                var p1 = pts[i - 1];
                                var p2 = pts[i];
                                var p3 = pts[Math.Min(pts.Count - 1, i + 1)];
                                var cp1 = new System.Windows.Point(
                                    p1.X + (p2.X - p0.X) * tension / 3.0,
                                    p1.Y + (p2.Y - p0.Y) * tension / 3.0);
                                var cp2 = new System.Windows.Point(
                                    p2.X - (p3.X - p1.X) * tension / 3.0,
                                    p2.Y - (p3.Y - p1.Y) * tension / 3.0);
                                ctx.BezierTo(cp1, cp2, p2, true, false);
                            }
                            ctx.LineTo(new System.Windows.Point(pts[^1].X, pT + cH), true, false);
                        }
                        fg.Freeze();
                        uint fillKey = ((uint)lineCol.R << 16) | ((uint)lineCol.G << 8) | lineCol.B;
                        if (!_fillBrushCacheFlat.TryGetValue(fillKey, out var fb))
                        {
                            // lighter on Dark: a strong fill on a dark card reads as a heavy block
                            bool darkBg = TryFindResource("BgDarkColor") is WpfColor bgc && bgc.R + bgc.G + bgc.B < 384;
                            fb = new System.Windows.Media.LinearGradientBrush(
                                WpfColor.FromArgb(darkBg ? (byte)40 : (byte)60, lineCol.R, lineCol.G, lineCol.B),  // next to the line
                                WpfColor.FromArgb(0, lineCol.R, lineCol.G, lineCol.B),                              // transparent at the bottom
                                new System.Windows.Point(0, 0), new System.Windows.Point(0, 1));
                            fb.Freeze();
                            _fillBrushCacheFlat[fillKey] = fb;
                        }
                        dc.DrawGeometry(fb, null, fg);
                    }

                    // Smooth Bezier line — 2px (pens created by MakeChartPen)
                    var lg = new StreamGeometry();
                    using (var ctx = lg.Open())
                    {
                        ctx.BeginFigure(pts[0], false, false);
                        const double tension = 0.35;
                        for (int i = 1; i < pts.Count; i++)
                        {
                            var p0 = pts[Math.Max(0, i - 2)];
                            var p1 = pts[i - 1];
                            var p2 = pts[i];
                            var p3 = pts[Math.Min(pts.Count - 1, i + 1)];
                            var cp1 = new System.Windows.Point(
                                p1.X + (p2.X - p0.X) * tension / 3.0,
                                p1.Y + (p2.Y - p0.Y) * tension / 3.0);
                            var cp2 = new System.Windows.Point(
                                p2.X - (p3.X - p1.X) * tension / 3.0,
                                p2.Y - (p3.Y - p1.Y) * tension / 3.0);
                            ctx.BezierTo(cp1, cp2, p2, true, false);
                        }
                    }
                    lg.Freeze();
                    dc.DrawGeometry(null, linePen, lg);
                    } // fine DrawRun

                    foreach (var run in runs) DrawRun(run);

                    // Dot at the end — on the last valid point of the last segment (not necessarily the last time slot, if that one is NaN/gap).
                    System.Windows.Point? lastPt = null;
                    for (int ri = runs.Count - 1; ri >= 0 && lastPt == null; ri--)
                        if (runs[ri].Count > 0) lastPt = runs[ri][^1];
                    if (lastPt == null) return;
                    var pts = new System.Collections.Generic.List<System.Windows.Point> { lastPt.Value };

                    uint colKey = ((uint)lineCol.R << 16) | ((uint)lineCol.G << 8) | lineCol.B;
                    if (!_dotBrushCache.TryGetValue(colKey, out var dotBr))
                    {
                        dotBr = new SolidColorBrush(lineCol); dotBr.Freeze();
                        _dotBrushCache[colKey] = dotBr;
                    }
                    ChartPulse.Draw(dc, pts[^1], lineCol);
                    dc.DrawEllipse(dotBr, null, pts[^1], 3.5, 3.5);

                    _ = showValueLabel; // parameter kept for call compatibility
                }

                DrawSeries(raw, pen, showFill, showValueLabel: true);
                if (raw2 != null && pen2 != null)
                    DrawSeries(raw2, pen2, showFill); // no label, but with a symmetric fill now
                dc.Pop();
            }
            RenderToCanvas(canvas, dv, w, h);
        }

        // DrawChartLine — all the logic is in DrawChart above; stub for leftover calls.
        private void DrawChartLine(
            System.Windows.Media.DrawingContext dc,
            float[] data, double w, double h,
            float yMin, double range,
            System.Windows.Media.Pen pen, bool showFill,
            System.Windows.Media.Color fillColor,
            double pT = 3, double pB = 2)
        {
            // No-op — the logic moved to DrawChart
        }
        private void UpdateHeroBar(float cpuPct, float ramPct, float cpuTemp, float gpuTemp)
        {
            if (TxtHeroVerdict == null) return;

            var issues = new System.Collections.Generic.List<string>();
            bool isCritical = false, isWarning = false;

            if (cpuPct > 90)      { issues.Add($"CPU {cpuPct:F0}% — very high load"); isCritical = true; }
            else if (cpuPct > 75) { issues.Add($"CPU {cpuPct:F0}% — high load"); isWarning = true; }

            if (ramPct > 90)      { issues.Add($"RAM {ramPct:F0}% full"); isCritical = true; }
            else if (ramPct > 80) { issues.Add($"RAM {ramPct:F0}% — consider closing apps"); isWarning = true; }

            if (!float.IsNaN(cpuTemp) && cpuTemp > 90) { issues.Add($"CPU {TempUnit.Fmt(cpuTemp)} — critical"); isCritical = true; }
            else if (!float.IsNaN(cpuTemp) && cpuTemp > 75) { issues.Add($"CPU {TempUnit.Fmt(cpuTemp)} — hot"); isWarning = true; }

            if (!float.IsNaN(gpuTemp) && gpuTemp > 85) { issues.Add($"GPU {TempUnit.Fmt(gpuTemp)} — hot"); isWarning = true; }

            // Sub-text: live metrics always visible
            var cpuStr  = cpuPct >= 0 ? $"CPU {cpuPct:F0}%" : "CPU —";
            var ramStr  = ramPct >= 0 ? $"RAM {ramPct:F0}%" : "RAM —";
            var tempStr = !float.IsNaN(cpuTemp) && cpuTemp > 0 ? $"{TempUnit.Fmt(cpuTemp)}" : "";
            var subParts = new System.Collections.Generic.List<string> { cpuStr, ramStr };
            if (!string.IsNullOrEmpty(tempStr)) subParts.Add(tempStr);

            // Fills the fields on the right of the hero bar with OS + uptime
            if (FindName("TxtHeroOsLine") is System.Windows.Controls.TextBlock osLine)
            {
                var osName = TxtOs?.Text ?? "";
                osLine.Text = string.IsNullOrEmpty(osName) ? "—" : osName;
            }
            if (FindName("TxtHeroUptimeLine") is System.Windows.Controls.TextBlock upLine)
            {
                var uptime = TxtUptime?.Text ?? "";
                upLine.Text = string.IsNullOrEmpty(uptime) ? "—" : uptime;
            }

            if (isCritical)
            {
                TxtHeroVerdict.Text = $"{issues.Count} critical issue{(issues.Count > 1 ? "s" : "")}";
                TxtHeroSub.Text = string.Join(" · ", issues);
                if (HeroIcon != null) { HeroIcon.Text = "!"; HeroIcon.Foreground = _brRed; }
                if (HeroIconBorder != null) HeroIconBorder.Background = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromArgb(30, 239, 68, 68));
                if (DashboardSkeleton != null) DashboardSkeleton.BorderBrush = _brRed;
            }
            else if (isWarning)
            {
                TxtHeroVerdict.Text = $"{issues.Count} warning{(issues.Count > 1 ? "s" : "")}";
                TxtHeroSub.Text = string.Join(" · ", issues) + "  ·  " + string.Join(" · ", subParts);
                if (HeroIcon != null) { HeroIcon.Text = "⚠"; HeroIcon.Foreground = _brOrange; }
                if (HeroIconBorder != null) HeroIconBorder.Background = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromArgb(30, 245, 158, 11));
                if (DashboardSkeleton != null) DashboardSkeleton.BorderBrush = _brOrange;
            }
            else
            {
                TxtHeroVerdict.Text = LanguageService.S("Dashboard", "AllSystemsHealthy");
                TxtHeroSub.Text = string.Join(" · ", subParts) + " · temps nominal";
                if (HeroIcon != null) { HeroIcon.Text = "✓"; HeroIcon.Foreground = (System.Windows.Media.Brush)TryFindResource("StatusSuccessBrush") ?? _brGreen; }
                if (HeroIconBorder != null) HeroIconBorder.Background = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromArgb(26, 34, 197, 94));
                if (DashboardSkeleton != null) DashboardSkeleton.ClearValue(System.Windows.Controls.Border.BorderBrushProperty);
            }
        }
        private static string CapStatus(string s)
        {
            if (string.IsNullOrEmpty(s)) return s;
            string cap = char.ToUpperInvariant(s[0]) + s[1..];
            return LanguageService.S("Dashboard", "State" + cap, cap);
        }

        /// <summary>
        /// State of the CPU / GPU card: comes from the temperature (the threshold in Settings), not from the load.
        /// Hot ≥ threshold · Warm ≥ threshold − 10 · Busy = high load (text colour, not a problem) · Idle (accent) · OK.
        /// </summary>
        private void UpdateComputeStatus(Border? pill, TextBlock? label, float loadPct, float tempC, float tempLimit,
            float busyAt, float idleBelow)
        {
            if (pill == null || label == null) return;
            bool hasTemp = !float.IsNaN(tempC) && tempC > 0;
            if (hasTemp && tempC >= tempLimit)
                SetStateLabel(label, LanguageService.S("Dashboard", "StateHot", "Hot"), _brRed);
            else if (hasTemp && tempC >= tempLimit - 10)
                SetStateLabel(label, LanguageService.S("Dashboard", "StateWarm", "Warm"), _brOrange);
            else if (loadPct >= busyAt)
                SetStateLabel(label, LanguageService.S("Dashboard", "StateBusy", "Busy"), (System.Windows.Media.Brush)FindResource("TextPrimaryBrush"));
            else if (loadPct < idleBelow)
                SetStateLabel(label, LanguageService.S("Dashboard", "StateIdle", "Idle"), (System.Windows.Media.Brush)FindResource("AccentBrush"));
            else
                SetStateLabel(label, LanguageService.S("Dashboard", "StateOk", "OK"), _brGreen);
        }

        private void UpdateStatusPill(Border? pill, TextBlock? label,
            float value, float critThresh, float warnThresh,
            string critLabel, string warnLabel, string okLabel)
        {
            if (pill == null || label == null) return;
            if (value >= critThresh)      SetStateLabel(label, CapStatus(critLabel), _brRed);
            else if (value >= warnThresh) SetStateLabel(label, CapStatus(warnLabel), _brOrange);
            else                          SetStateLabel(label, CapStatus(okLabel), _brGreen);
        }

        /// <summary>
        /// Changes the state label (Cool → Warm → Hot, Ok → High): the text fades briefly, and the colour moves smoothly from the
        /// old one to the new one. The animation runs only at the moment of change and only with animations on.
        /// </summary>
        private static void SetStateLabel(TextBlock label, string text, System.Windows.Media.Brush brush)
        {
            if (label.Text == text) { label.Foreground = brush; return; }
            if (label.Text.Length == 0 || !label.IsLoaded || !SettingsService.Current.EnableAnimations)
            {
                label.Text = text; label.Foreground = brush;
                return;
            }
            var from = (label.Foreground as System.Windows.Media.SolidColorBrush)?.Color;
            var to = (brush as System.Windows.Media.SolidColorBrush)?.Color;
            var fadeOut = new System.Windows.Media.Animation.DoubleAnimation(1, 0.2, TimeSpan.FromMilliseconds(90));
            fadeOut.Completed += (_, _) =>
            {
                label.Text = text;
                if (from.HasValue && to.HasValue)
                {
                    var blend = new System.Windows.Media.SolidColorBrush(from.Value);
                    label.Foreground = blend;
                    blend.BeginAnimation(System.Windows.Media.SolidColorBrush.ColorProperty,
                        new System.Windows.Media.Animation.ColorAnimation(from.Value, to.Value, TimeSpan.FromMilliseconds(240)));
                }
                else label.Foreground = brush;
                label.BeginAnimation(UIElement.OpacityProperty,
                    new System.Windows.Media.Animation.DoubleAnimation(0.2, 1, TimeSpan.FromMilliseconds(160)));
            };
            label.BeginAnimation(UIElement.OpacityProperty, fadeOut);
        }

        private void UpdateDashboardRam()
        {
            if (TxtDashRamPct == null) return;
            try
            {
                var (usedMB, totalMB) = SMDWin.Services.WmiCache.Instance.GetRamUsage();
                if (totalMB == 0) return;

                double totalGB = totalMB / 1024.0;
                double usedGB  = usedMB  / 1024.0;
                double pct     = usedGB / totalGB * 100;

                AnimateValue(TxtDashRamPct, pct, "");
                TxtDashRamUsed.Text = $"{usedGB:F1}";
                if (TxtRamDashSub != null) TxtRamDashSub.Text = $" / {SMDWin.Services.UnitFormat.RamTotalLabelFromMB(totalMB)}";

                TxtDashRamPct.Foreground = pct > 85 ? _brRed
                    : pct > 70 ? _brOrange
                    : _brGreen;
                if (DashRamCard != null)
                    UpdateCardAlert(DashRamCard, pct > 90, ref _ramAlertSince);

            }
            catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.UpdateDashboardRam"); }
        }

        /// <summary>
        /// Applies a persistent red glow to <paramref name="card"/> once
        /// <paramref name="isCritical"/> has been true for ≥ <see cref="AlertDelay"/>.
        /// Reverts to the normal shadow immediately when load drops below threshold.
        /// Uses pre-frozen Effect instances — zero allocation per tick.
        /// </summary>
        private void UpdateCardAlert(Border card, bool isCritical, ref DateTime? alertSince)
        {
            if (isCritical)
            {
                alertSince ??= DateTime.UtcNow;
                // the coloured outline and the glow behind the row (after the delay); no Effect on the card itself, it blurs the text
                SetDashRowAlert(card, (DateTime.UtcNow - alertSince.Value) >= AlertDelay);
            }
            else
            {
                alertSince = null;
                SetDashRowAlert(card, false);
                // Always clear local value so Style's IsMouseOver trigger works freely.
                // ReadLocalValue check avoids redundant layout passes when already clear.
                if (card.ReadLocalValue(Border.EffectProperty) != DependencyProperty.UnsetValue)
                    card.ClearValue(Border.EffectProperty);
            }
        }

        private static void UpdateStressTempLabel(TextBlock valLbl, TextBlock mmLbl,
            float? temp, ref float? mn, ref float? mx)
        {
            if (!temp.HasValue || temp <= 0) { valLbl.Text = "--"; return; }
            float v = temp.Value;
            mn = mn.HasValue ? Math.Min(mn.Value, v) : v;
            mx = mx.HasValue ? Math.Max(mx.Value, v) : v;

            valLbl.Text = $"{TempUnit.Fmt(v)}";
            valLbl.Foreground = v > 90 ? _brRed : v > 75 ? _brOrange : _brGreen;
            mmLbl.Text = $"Min {TempUnit.Fmt(mn)}  /  Max {TempUnit.Fmt(mx)}"; // hidden stub — harmless
        }

        private float ReadKernelFreqMHz()
        {
            try
            {
                // PerformanceCounter: Processor Information -> % Processor Performance
                // gives current freq as % of base. Compare with max from WMI.
                using var pc = new System.Diagnostics.PerformanceCounter(
"Processor Information", "% Processor Performance", "_Total");
                pc.NextValue(); // prime — first call always 0
                System.Threading.Thread.Sleep(50); // minimal wait in background thread (runs on Task.Run)
                float perfPct = pc.NextValue();

                // Get max/base freq from WMI
                float maxMHz = 0;
                try
                {
                    using var wmi = SMDWin.Services.WmiHelper.Searcher(
"SELECT MaxClockSpeed FROM Win32_Processor", System.TimeSpan.FromSeconds(10));
                    using (var __wmiTmp4 = wmi.Get())
                    {
                        foreach (System.Management.ManagementObject o in __wmiTmp4)
                        maxMHz = Convert.ToSingle(o["MaxClockSpeed"]);
                    }
                }
                catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.ReadKernelFreqMHz"); }

                if (maxMHz > 0 && perfPct > 0)
                    return maxMHz * perfPct / 100f;
            }
            catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.ReadKernelFreqMHz"); }
            return 0f;
        }


